const req = $('Webhook').first().json.body || $('Webhook').first().json;
const centerCode = String(req.center_code || '').trim().toUpperCase();
const reportDate = String(req.report_date || '').trim();
const spreadsheetId = String(req.spreadsheet_id || req.spreadsheetId || '').trim();
const targetSheet = String(req.targetSheet || req.target_sheet || 'BaoCao').trim();

if (!/^[a-zA-Z0-9_-]{20,}$/.test(spreadsheetId)) throw new Error('Spreadsheet ID không hợp lệ.');
if (!targetSheet) throw new Error('Thiếu tên tab Google Sheet.');
if (!Array.isArray(req.items) || req.items.length === 0) throw new Error('Không có dữ liệu để xuất.');

const centerNames = {
  'R4001001': 'Trung tâm CSKH vivo HCM Hòa Bình',
  'R4001002': 'Trung tâm CSKH vivo Hà Nội',
  'R4001003': 'Trung tâm CSKH vivo Cần Thơ',
  'R4001005': 'Trung tâm CSKH vivo Hải Phòng',
  'R4001007': 'Trung tâm CSKH vivo HCM Phú Lợi',
  'R4001008': 'Trung tâm CSKH vivo Đà Nẵng',
  'R4001009': 'Trung tâm CSKH vivo Đồng Tháp',
  'R4001010': 'Trung tâm CSKH vivo Nghệ An',
  'R4001011': 'Trung tâm CSKH vivo Đắk Lắk',
  'R4001012': 'Trung tâm CSKH vivo Cà Mau',
  'R4001015': 'Trung tâm CSKH vivo Phú Thọ',
  'R4001017': 'Trung tâm CSKH vivo HCM Xuân Hòa',
  'R4001021': 'Trung tâm CSKH vivo Đồng Nai',
  'R4001023': 'Trung tâm CSKH vivo Gia Lai',
  'R4001026': 'Trung tâm CSKH vivo HCM An Khánh'
};

const resolveCenterName = (row, code) => {
  const raw = String(row['Tên TTBH'] || row['TTBH'] || centerNames[code] || code || row['Mã TTBH'] || '').trim();
  return centerNames[raw] || raw;
};

const expectedName = (centerNames[centerCode] || '').trim().toUpperCase();

const formatMoney = value => {
  if (value === '-' || value === ' - ' || value === '—') return '-';
  if (value === '' || value === null || value === undefined) return '';
  if (typeof value === 'string' && value.includes(',')) return value.trim();
  const parsed = typeof value === 'number' ? value : Number(String(value).replace(/,/g, ''));
  return Number.isFinite(parsed) ? new Intl.NumberFormat('en-US').format(Math.round(parsed)) : '';
};

const rows = req.items
  .filter(row => {
    const rowCenter = String(row['Mã TTBH'] || row['TTBH'] || '').trim().toUpperCase();
    const rowDate = String(row['Ngày báo cáo'] || row['Ngày'] || '').trim();
    const matchCenter = !centerCode || rowCenter === centerCode || (expectedName && rowCenter === expectedName);
    const matchDate = !reportDate || reportDate === 'ALL' || rowDate === reportDate;
    return matchCenter && matchDate;
  })
  .map(row => {
    const isTgdd = String(row['Khách hàng'] || '').trim().toUpperCase() === 'TGDĐ';
    return {
      json: {
        'Ngày': String(row['Ngày báo cáo'] || row['Ngày'] || reportDate || ''),
        'Số phiếu sửa chữa': String(row['Số phiếu sửa chữa'] || ''),
        'Mã vật tư linh kiện': String(row['Mã vật tư linh kiện'] || ''),
        'Tên vật tư': String(row['Tên vật tư'] || ''),
        'Xuất Bảo Hành': row['Xuất Bảo Hành'] === 1 || row['Xuất Bảo Hành'] === '1' ? 1 : '',
        'Xuất phụ kiện': row['Xuất phụ kiện'] === 1 || row['Xuất phụ kiện'] === '1' ? 1 : '',
        'Xuất Sửa Chữa': row['Xuất Sửa Chữa'] === 1 || row['Xuất Sửa Chữa'] === '1' ? 1 : '',
        'Đơn giá': formatMoney(row['Đơn giá']),
        'Doanh thu tiền mặt': isTgdd ? '0' : formatMoney(row['Doanh thu tiền mặt']),
        'Doanh thu tiền mặt trước thuế': isTgdd ? '0' : formatMoney(row['Doanh thu tiền mặt trước thuế']),
        'Công nợ': isTgdd ? formatMoney(row['Công nợ']) : '0',
        'CN sau chiết khấu': isTgdd ? formatMoney(row['CN sau chiết khấu']) : '-',
        'CN trước thuế': isTgdd ? formatMoney(row['CN trước thuế']) : '-',
        'Khách hàng': String(row['Khách hàng'] || ''),
        'Phương thức thanh toán': String(row['Phương thức thanh toán'] || ''),
        'Jobcard': String(row['Jobcard'] || ''),
        'TTBH': resolveCenterName(row, centerCode)
      }
    };
  });

if (rows.length === 0) throw new Error('Không còn dòng hợp lệ sau khi kiểm tra TTBH và ngày báo cáo.');
return rows;
